    n_ok = 0
    n_tot = 0
    t0 = time.time()

    for pi, prob in enumerate(problems):
        pid = prob["id"]
        gold = prob["answer"]
        ipath = os.path.join(int_dir, f"{pid}.json")

        if args.resume and os.path.exists(ipath):
            with open(ipath) as f:
                cached = json.load(f)
            if cached.get("final_answer") == gold:
