            "gold_answer": gold,
            "final_answer": final,
            "correct": ok,
            "vote_counts": votes,
            "rounds": rounds,
        }
        results.append(entry)

        with open(ipath, "w") as f:
            json.dump(entry, f, indent=2, default=str)

        if (pi + 1) % 10 == 0 or pi == len(problems) - 1:
            elapsed = time.time() - t0
            logger.info(
                "[%d/%d] bv=%.2f%% (%.1fs)",
                pi + 1, len(problems), 100 * n_ok / n_tot, elapsed,
