    print("Backward Verification Results (Exp 5)")
    print(f"{'=' * 60}")
    print(f"N={n_tot}  K={args.k}")
    print(f"BV accuracy:  {bv_acc:.4f} ({n_ok}/{n_tot})")
    print(f"SC baseline:  {sc_acc:.4f}")
    print(f"Delta:        {(bv_acc - sc_acc) * 100:+.2f}pp")
    for at, st in per_type.items():
